"""Register a small paired preservation experiment before any training."""
import importlib,json,time
core=importlib.import_module('pepe-elite-core');ROOT,RUN=core.ROOT,core.RUN

def main():
 if (RUN/'registration.json').exists():raise ValueError('Study already registered; resume instead')
 original=ROOT/'work/pepe-finrl-mask-v3';reg=core.read(original/'registration.json')
 for path,digest in {**reg['sourceHashes'],**reg['dataHashes'],**reg['dependencyHashes']}.items():
  if core.sha(ROOT/path)!=digest:raise ValueError('Frozen V3 input changed: '+path)
 cp=core.read(original/'checkpoint.json');best=cp['bestAudit']['archive'];initial=core.read(original/'parent-selection.json')['archive'];parents=[]
 for n,(label,archive)in enumerate([('Campeão V3 G'+str(best['generation']),best),('Pai inicial V3',initial)]):
  if core.sha(ROOT/archive['modelPath'])!=archive['modelSHA256']:raise ValueError('Archived parent hash mismatch')
  target=RUN/'parents'/f'p{n}.zip';core.copy_once(ROOT/archive['modelPath'],target)
  evaluation=core.read(ROOT/archive['evaluationPath']);core.immutable(RUN/'parents'/f'p{n}-evidence.json',{'archive':archive,'evaluation':evaluation})
  parents.append({'id':n,'label':label,'modelPath':str(target.relative_to(ROOT)),'modelSHA256':core.sha(target),'sourceArchive':archive,'expectedAudit':core.compact(evaluation['audit']),'hyperparameters':archive['hyperparameters']})
 if len({p['modelSHA256']for p in parents})!=2:raise ValueError('The two parent policies must be distinct')
 policy=core.read(ROOT/'pepe-finrl-mask-protocol.json')
 protocol={'version':'pepe-elite-study-v1','createdAt':int(time.time()*1000),'parents':parents,'rounds':10,'pairsPerParent':3,'trainableChildren':12,'frozenParents':2,'seed':20261021,'stepsPerRound':1024,'workerProcesses':1,'threadsPerWorker':2,'train':policy['train'],'excludedTraining':policy['excludedTraining'],'development':policy['development'],'capitalBRL':policy['capitalBRL'],'fx':policy['fx'],'cost':policy['trainingCost'],'risk':policy['risk'],'dailyLimit':policy['dailyLimit'],'totalLimit':policy['totalLimit'],'allowedLeverages':policy['allowedLeverages'],'drawdownPenalty':policy['drawdownPenalty'],'mutation':False,'arms':{'control':'Continue from the previous trained candidate, including regressions.','protected':'Train a copy of the last accepted child. Adopt only when full-calendar score strictly improves; otherwise retain that incumbent.'},'parentReevaluation':'Founding parents never train. Re-evaluate their exact tensors each round; any change in tensors or score aborts.','pairing':'Three predeclared seeds per parent, same seed and hyperparameters in both arms per round. Round-one tensors must match. Each arm receives exactly 1024 training steps per round. Candidate results, including rejected models and no-trade outcomes, remain in raw means.','primaryDescriptiveMetrics':['raw candidate mean and median net BRL by arm and round','paired candidate net BRL differences','positive/negative/cash/halts proportions','fees, slippage, gross and drawdown'],'retainedCurve':'Selection on this same development calendar guarantees nondecreasing retained score by construction. It is not a portfolio curve, compounding, an independent profit estimate or a training-quality metric.','sampleLimitation':'Six dependent pairs from two selected parents; descriptive pilot, no significance or generalization claim.','finalTest':'Locked. October–December 2024 already used extensively for selection. No old validation/final calendar is opened.','resources':'One additional worker only when V3 capacity is at most three workers and free memory >=20%; close worker while waiting. V3 is neither paused nor changed.','termination':'Ten rounds, manual pause/error or disk <10GiB. No automatic scale-up or promotion to real trading.','realOrders':False,'automaticPromotionToV3':False,'sourceV3GenerationAtRegistration':cp['generation'],'originalV3RegistrationSHA256':core.sha(original/'registration.json')}
 core.immutable(RUN/'protocol.json',protocol)
 sources=['scripts/pepe-elite-core.py','scripts/pepe-elite-worker.py','scripts/run-pepe-elite.py','scripts/prepare-pepe-elite.py','scripts/local-pepe-elite.mjs','scripts/pepe-mask-worker.py','scripts/pepe_mask_env.py','scripts/pepe_finrl_env.py','scripts/pepe-mask-bridge.mjs','scripts/pepe-mask-engine.mjs','scripts/pepe-mask-actions.mjs','scripts/run-pepe-mask-ultra.py','scripts/run-pepe-mask.py','scripts/pepe-mask-core.py','pepe-finrl-mask-protocol.json','pepe-finrl-protocol.json']
 registration={'registeredAt':int(time.time()*1000),'protocolSHA256':core.sha(RUN/'protocol.json'),'originalV3RegistrationSHA256':core.sha(original/'registration.json'),'sourceHashes':{**reg['sourceHashes'],**{p:core.sha(ROOT/p)for p in sources}},'dataHashes':reg['dataHashes'],'dependencyHashes':reg['dependencyHashes'],'parentHashes':{**{p['modelPath']:p['modelSHA256']for p in parents},**{str((RUN/'parents'/f'p{p["id"]}-evidence.json').relative_to(ROOT)):core.sha(RUN/'parents'/f'p{p["id"]}-evidence.json')for p in parents}},'noIndependentProfitProof':True}
 core.immutable(RUN/'registration.json',registration)
 core.atomic(RUN/'control.json',{'desired':'paused','updatedAt':int(time.time()*1000)})
 core.atomic(RUN/'checkpoint.json',{'round':0,'history':[],'baselines':{},'incumbents':{}})
 status={'app':'trend-lab-pepe-elite-study','status':'registered','round':0,'targetRounds':10,'jobsCompleted':0,'targetJobs':142,'protocol':protocol,'history':[],'registeredAt':registration['registeredAt'],'realOrders':False}
 core.atomic(RUN/'status.json',status);core.atomic(ROOT/'web/data/pepe-elite-study.json',status)
 print(json.dumps({'registered':True,'parents':[{'label':p['label'],'score':p['expectedAudit']['score'],'pnlBRL':p['expectedAudit']['pnlBRL']}for p in parents],'trainableChildren':12,'rounds':10,'v3Untouched':True}))
if __name__=='__main__':main()
